nodes.command:
mkdir -p workflows/project/logs/audits && cat << 'PROGRESS_EOF' > "workflows/project/logs/audits/${nodes.intake.output.audit_id}-progress.md"
# 进度报告

> 审核ID: ${nodes.intake.output.audit_id}
> 生成时间: $(date '+%Y-%m-%d %H:%M:%S')
> 统计周期: ${nodes.intake.output.period.start} ~ ${nodes.intake.output.period.end}

## 总体状态: ${nodes.generate_progress_report.output.status}

## 关键指标

| 指标 | 数值 |
|---|---|
| 周期内任务数 | ${nodes.generate_progress_report.output.metrics.tasks_in_period} |
| 周期内提交数 | ${nodes.generate_progress_report.output.metrics.commits_in_period} |
| 完成审查数 | ${nodes.generate_progress_report.output.metrics.reviews_completed} |
| 通过审查数 | ${nodes.generate_progress_report.output.metrics.reviews_passed} |
| 综合通过率 | ${nodes.generate_progress_report.output.metrics.overall_pass_rate} |
| 代码审查均分 | ${nodes.generate_progress_report.output.metrics.code_review_avg_score} |

## 审查明细

### 代码审查
- 数量: ${nodes.generate_progress_report.output.breakdown.code_review.count}
- 通过: ${nodes.generate_progress_report.output.breakdown.code_review.passed}

### 设计审查
- 数量: ${nodes.generate_progress_report.output.breakdown.design_review.count}
- 通过: ${nodes.generate_progress_report.output.breakdown.design_review.passed}

### QA签字
- 数量: ${nodes.generate_progress_report.output.breakdown.qa_signoff.count}
- 通过: ${nodes.generate_progress_report.output.breakdown.qa_signoff.passed}

## 决策建议

**决策**: ${nodes.generate_recommendations.output.decision}

### 建议
$(echo '${nodes.generate_recommendations.output.recommendations.join("\n")}' | sed 's/^/- /')

### 下一步
$(echo '${nodes.generate_recommendations.output.next_steps.join("\n")}' | sed 's/^/- /')
PROGRESS_EOF
